import rclpy
from rclpy.node import Node
from std_msgs.msg import Float32
import cv2
import numpy as np
import time


class AnglePublisher(Node):
    def __init__(self):
        super().__init__('angle_publisher')
        self.publisher_ = self.create_publisher(Float32, 'angle_topic', 10)
        self.timer = self.create_timer(0.01, self.publish_angle)  # Publica 0.1 s

        # Definición de las dimensiones del tablero de ajedrez
        self.CHECKERBOARD = (5, 7)  # Cambié el número de esquinas a 5 y 7
        self.criteria = (cv2.TERM_CRITERIA_EPS + cv2.TERM_CRITERIA_MAX_ITER, 30, 0.001)

        # Vectores para almacenar puntos 3D y 2D para cada imagen del tablero
        self.objpoints = []
        self.imgpoints = []

        # Definir las coordenadas del mundo para los puntos 3D
        self.objp = np.zeros((1, self.CHECKERBOARD[0] * self.CHECKERBOARD[1], 3), np.float32)
        self.objp[0, :, :2] = np.mgrid[0:self.CHECKERBOARD[0], 0:self.CHECKERBOARD[1]].T.reshape(-1, 2) * 2.5

        self.calibrated = False
        self.angle = 0.0
        self.cap = cv2.VideoCapture(0)  # Captura desde la cámara web

        # Comprobar si la cámara se abrió correctamente
        if not self.cap.isOpened():
            self.get_logger().error("Error al abrir la cámara.")
            exit()
        
        # Para ajustar tamaño de las ventanas
        self.width = 1440
        self.height = 810
        self.dim = (self.width, self.height)

    def calibrate_camera(self):
        # Capturar frames suficientes para la calibración
        frame_count = 0
        while frame_count < 70:  # Capturamos 70 frames
            ret, frame = self.cap.read()
            if not ret:
                self.get_logger().error("No se pudo capturar el frame.")
                break

            gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            ret, corners = cv2.findChessboardCorners(gray, self.CHECKERBOARD,
                                                     cv2.CALIB_CB_ADAPTIVE_THRESH + cv2.CALIB_CB_FAST_CHECK +
                                                     cv2.CALIB_CB_NORMALIZE_IMAGE)

            if ret:
                frame_count += 1
                self.objpoints.append(self.objp)
                corners2 = cv2.cornerSubPix(gray, corners, (11, 11), (-1, -1), self.criteria)
                self.imgpoints.append(corners2)
                cv2.drawChessboardCorners(frame, self.CHECKERBOARD, corners2, ret)
            
            #Ajustar el tamaño de la ventana
            frame = cv2.resize(frame, self.dim, interpolation=cv2.INTER_AREA)
            # Mostrar los frames con las esquinas detectadas
            cv2.imshow("Calibración de Cámara", frame)
            cv2.waitKey(1)  # Esperar 1 ms para no bloquear la cámara

        # Realizar la calibración de la cámara
        ret, mtx, dist, rvecs, tvecs = cv2.calibrateCamera(self.objpoints, self.imgpoints, gray.shape[::-1], None, None)
        self.mtx = mtx
        self.dist = dist
        self.rvecs = rvecs
        self.tvecs = tvecs
        self.calibrated = True
        self.get_logger().info("Calibración de la cámara completada.")

        # Cerrar la ventana de calibración
        cv2.destroyWindow("Calibración de Cámara")

    def calculate_angle(self, frame):
        # Si la cámara está calibrada, calcular el ángulo
        if self.calibrated:
            gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            ret, corners = cv2.findChessboardCorners(gray, self.CHECKERBOARD,
                                                     cv2.CALIB_CB_ADAPTIVE_THRESH + cv2.CALIB_CB_FAST_CHECK +
                                                     cv2.CALIB_CB_NORMALIZE_IMAGE)

            if ret:
                # Realizar el cálculo del ángulo para cada nuevo frame
                # Estimar la rotación y traslación del patrón con respecto a la cámara
                retval, rvec, tvec = cv2.solvePnP(self.objp, corners, self.mtx, self.dist)

                if retval:
                    # Convertir el vector de rotación a matriz de rotación
                    R, _ = cv2.Rodrigues(rvec)

                    # El vector normal al plano del patrón de ajedrez (por ejemplo, [0, 0, 1])
                    normal = np.array([0, 0, 1])

                    # El eje z de la cámara en la matriz de rotación es R[:, 2]
                    cam_z = R[:, 2]

                    # Calcular el coseno del ángulo usando el producto punto
                    cos_angle = np.dot(normal, cam_z) / (np.linalg.norm(normal) * np.linalg.norm(cam_z))

                    # Calcular el ángulo en radianes y luego convertir a grados
                    angle = np.arccos(cos_angle)
                    self.angle = np.degrees(angle)

                    # Dibujar las esquinas del tablero de ajedrez
                    cv2.drawChessboardCorners(frame, self.CHECKERBOARD, corners, ret)

        return frame

    def publish_angle(self):
        
        # Publica el ángulo calculado
        angle_msg = Float32()
        angle_msg.data = self.angle  # Asigna tu ángulo calculado aquí
        self.publisher_.publish(angle_msg)

        self.get_logger().info(f'Publicando ángulo: {self.angle:.2f} grados')  # Mostrar en la terminal

    def run(self):
        # Calibrar la cámara antes de calcular el ángulo en tiempo real
        self.calibrate_camera()

        # Capturar frames en tiempo real
        while rclpy.ok():
            ret, frame = self.cap.read()
            if not ret:
                self.get_logger().error("No se pudo capturar el frame.")
                break
            # Para observar cuanto tarda cada iteración 
            start_time =time.time()
            
            # Calcular el ángulo con el frame actual
            frame = self.calculate_angle(frame)
            
            #Ajustar el tamaño de la ventana
            frame = cv2.resize(frame, self.dim, interpolation=cv2.INTER_AREA)
            
            # Mostrar el frame con el patrón de ajedrez y el ángulo calculado
            cv2.putText(frame, f'Angulo: {self.angle:.2f} grados', (10, 30), cv2.FONT_HERSHEY_SIMPLEX, 0.8, (0, 255, 0),
                        2)
            cv2.imshow("Cámara", frame)

            # Publicar el ángulo cada vez que se actualiza
            self.publish_angle()
            
            end_time = time.time()
            elapsed_time = end_time - start_time
            
            self.get_logger().info(f'Tiempo de iteración: {elapsed_time:.4f} segundos')
            # Esperar por la tecla 'q' para salir
            if cv2.waitKey(1) & 0xFF == ord('q'):
                break

        self.cap.release()
        cv2.destroyAllWindows()


def main(args=None):
    rclpy.init(args=args)
    angle_publisher = AnglePublisher()
    angle_publisher.run()
    angle_publisher.destroy_node()
    rclpy.shutdown()


if __name__ == '__main__':
    main()
